import * as THREE from 'three';
import {TransformControls} from './vendor/TransformControls.js';
import {ensureCAD,newEntity,cadId,resolveShape,profileFor,validateProfile,validateCAD,offsetProfile,makeComponent,makeUnique,duplicateEntity,groupEntities,snapPoint} from './cad-data.js';
import {modelObject,booleanEntity,importModel,exportDXF,geometryData} from './cad-geometry.js';
import {floorBounds} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rounded=n=>Math.round(n*10000)/10000;
export function mountCADStudio(bridge){let active=false,section='create',ids=[],drawing=null,points=[],snap=.1,mode='translate',space='world',root=null,gizmo=null,pivot=null,dragging=false,beforeTransforms=null,boxes=[],lastFloor=null,rememberedHome=null;
const doc=()=>ensureCAD(bridge.getProject()),scene=bridge.getScene(),entities=()=>doc().entities.filter(e=>e.floorId===bridge.getFloorId()),selected=()=>entities().filter(e=>ids.includes(e.id)),canEdit=()=>selected().length&&selected().every(e=>!e.locked);
ensureCAD(bridge.getProject());
const button=document.createElement('button');button.className='rail-btn';button.id='model-studio-btn';button.innerHTML='<svg><use href="#i-cube"/></svg><span>Model</span>';button.onclick=()=>activate();$('.rail').insertBefore(button,$('.rail [data-tab="materials"]'));
const input=document.createElement('input');input.type='file';input.accept='.glb,.obj,.stl';input.hidden=true;document.body.append(input);input.onchange=async()=>{const file=input.files[0];input.value='';if(!file)return;try{bridge.toast('Reading the static model…');const entity=await importModel(file,bridge.getFloorId());validateCAD({...structuredClone(doc()),entities:[...doc().entities,entity]},bridge.getProject().floors.map(f=>f.id));change(cad=>cad.entities.push(entity));ids=[entity.id];refresh();fitSelection();bridge.toast('Imported static geometry. Check its units and scale.');}catch(error){bridge.toast(error.message);}};
function change(fn){bridge.mutate(p=>{const cad=ensureCAD(p);fn(cad);validateCAD(cad,p.floors.map(f=>f.id));});}
function safe(fn){try{return fn();}catch(error){bridge.toast(error.message);}}
function dispose(object){object?.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});}
function clearBoxes(){for(const box of boxes){scene?.scene.remove(box);box.geometry.dispose();box.material.dispose();}boxes=[];}
function visible(e){return e.visible&&doc().tags.find(t=>t.id===e.tagId)?.visible;}
function updateModels(){if(!scene)return;gizmo?.detach();clearBoxes();if(root){scene.content.remove(root);dispose(root);}root=new THREE.Group();root.name='Hestia CAD models';scene.content.add(root);for(const e of entities().filter(visible))root.add(modelObject(doc(),e));ids=ids.filter(id=>entities().some(e=>e.id===id));applyView();attachGizmo();}
function attachGizmo(){if(!scene||!gizmo||dragging)return;gizmo.detach();clearBoxes();if(pivot?.userData.cadPivot&&pivot.parent){for(const child of [...pivot.children])root.attach(child);pivot.removeFromParent();}pivot=null;const objects=[];root?.traverse(o=>{if(o.userData.kind==='cad'&&ids.includes(o.userData.id))objects.push(o);});for(const object of objects){const box=new THREE.BoxHelper(object,'#c0a5fa');scene.scene.add(box);boxes.push(box);}if(!active||!canEdit()||!objects.length)return;
if(objects.length===1)pivot=objects[0];else{const bounds=new THREE.Box3();for(const object of objects)bounds.expandByObject(object);pivot=new THREE.Group();pivot.name='Selection pivot';pivot.userData.cadPivot=true;pivot.position.copy(bounds.getCenter(new THREE.Vector3()));root.add(pivot);for(const object of objects)pivot.attach(object);}gizmo.attach(pivot);gizmo.setMode(mode);gizmo.setSpace(space);gizmo.setTranslationSnap(snap||null);gizmo.setRotationSnap(THREE.MathUtils.degToRad(15));gizmo.setScaleSnap(.1);}
function applyView(){if(!scene)return;const view=doc().view;scene.renderer.clippingPlanes=view.section.enabled?[new THREE.Plane(new THREE.Vector3(view.section.axis==='x'?-1:0,view.section.axis==='y'?-1:0,view.section.axis==='z'?-1:0),view.section.offset)]:[];scene.content.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){m.userData.hestiaOriginal??={color:m.color?.clone(),map:m.map,opacity:m.opacity,transparent:m.transparent,wireframe:m.wireframe,depthWrite:m.depthWrite};const original=m.userData.hestiaOriginal;if(m.color)m.color.copy(view.style==='monochrome'?new THREE.Color('#d1d1cb'):original.color);m.map=view.style==='monochrome'?null:original.map;m.wireframe=view.style==='wireframe';m.transparent=view.style==='xray'||original.transparent;m.opacity=view.style==='xray'?.25:original.opacity;m.depthWrite=view.style==='xray'?false:original.depthWrite;m.needsUpdate=true;}});}
if(scene){gizmo=new TransformControls(scene.camera,scene.canvas);gizmo.setSize(.75);scene.scene.add(gizmo.getHelper());gizmo.addEventListener('objectChange',()=>boxes.forEach(b=>b.update()));gizmo.addEventListener('dragging-changed',e=>{scene.controls.enabled=!e.value;dragging=e.value;if(e.value){beforeTransforms=new Map(selected().map(e=>[e.id,{position:[...e.position],rotation:[...e.rotation],scale:[...e.scale]}]));}else if(beforeTransforms){const updates=[];root.updateMatrixWorld(true);root.traverse(o=>{if(o.userData.kind!=='cad'||!ids.includes(o.userData.id))return;const p=new THREE.Vector3(),q=new THREE.Quaternion(),s=new THREE.Vector3();o.matrixWorld.decompose(p,q,s);const euler=new THREE.Euler().setFromQuaternion(q,'XYZ');updates.push({id:o.userData.id,position:p.toArray().map(rounded),rotation:[euler.x,euler.y,euler.z].map(THREE.MathUtils.radToDeg).map(rounded),scale:s.toArray().map(rounded)});});beforeTransforms=null;if(updates.length)safe(()=>change(cad=>{for(const update of updates){const e=cad.entities.find(e=>e.id===update.id);Object.assign(e,update);}}));}});
const oldLoad=scene.load.bind(scene);scene.load=(...args)=>{gizmo.detach();clearBoxes();root=null;oldLoad(...args);updateModels();};const oldResize=scene.resize.bind(scene);scene.resize=()=>{oldResize();if(scene.camera.isOrthographicCamera){const r=scene.canvas.parentElement.getBoundingClientRect();scene.camera.left=-scene.camera.top*r.width/Math.max(1,r.height);scene.camera.right=-scene.camera.left;scene.camera.updateProjectionMatrix();}};
const oldDown=scene.down.bind(scene);scene.down=e=>{if(gizmo.axis)return;const hits=scene.hit(e).filter(h=>!doc().view.section.enabled||h.point[doc().view.section.axis]<=doc().view.section.offset+.001);let object=hits[0]?.object;while(object&&!object.userData.id)object=object.parent;if(object?.userData.kind==='cad'){activate(false);choose(object.userData.id,e.shiftKey||e.ctrlKey||e.metaKey);return;}if(active&&object?.userData.kind==='item')deactivate();oldDown(e);};const oldHome=scene.home.bind(scene);scene.home=()=>{oldHome();if(entities().length)fitAll();};}
function activate(show3D=true){rememberedHome=bridge.getHomeSelection()||rememberedHome;active=true;button.classList.add('active');$$('[data-tab]').forEach(b=>b.classList.remove('active'));bridge.clearSelection();if(show3D)bridge.setView('3d');refresh();document.querySelector('#panel-content').scrollTop=0;}
function deactivate(){if(!active)return;active=false;drawing=null;points=[];button.classList.remove('active');gizmo?.detach();clearBoxes();$('#inspector').classList.remove('has-selection');bridge.render();}
$$('[data-tab]').forEach(b=>b.addEventListener('click',deactivate));
function choose(id,add=false){const e=entities().find(e=>e.id===id);if(!e)return;let next=e.groupId?entities().filter(a=>a.groupId===e.groupId).map(a=>a.id):[id];ids=add?[...new Set([...ids,...next])]:next;bridge.clearSelection();refresh();}
function add(type,params){const b=floorBounds(bridge.getFloor()),e=newEntity(type,bridge.getFloorId(),params,[b.x+b.w/2,['rectangle','circle','polygon','line'].includes(type)?.04:0,b.z+b.d/2]);change(cad=>cad.entities.push(e));ids=[e.id];bridge.setView('3d');refresh();}
function fitAll(){if(!scene)return;const b=new THREE.Box3().setFromObject(scene.content),sphere=b.getBoundingSphere(new THREE.Sphere());if(!Number.isFinite(sphere.radius))return;const radius=Math.max(sphere.radius,2),target=sphere.center,direction=new THREE.Vector3(1,1.15,1.35).normalize();scene.controls.target.copy(target);scene.camera.up.set(0,1,0);scene.camera.position.copy(target).addScaledVector(direction,radius*3.2);if(scene.camera.isOrthographicCamera){scene.camera.top=radius*1.25;scene.camera.bottom=-scene.camera.top;scene.resize();}scene.controls.update();}
function fitSelection(){if(!scene||!ids.length){fitAll();return;}const b=new THREE.Box3();root.traverse(o=>{if(o.userData.kind==='cad'&&ids.includes(o.userData.id))b.expandByObject(o);});if(b.isEmpty())return;const sphere=b.getBoundingSphere(new THREE.Sphere());scene.controls.target.copy(sphere.center);scene.camera.position.copy(sphere.center).add(new THREE.Vector3(1,1.1,1.3).normalize().multiplyScalar(Math.max(2,sphere.radius*4)));if(scene.camera.isOrthographicCamera){scene.camera.top=Math.max(1,sphere.radius*1.3);scene.camera.bottom=-scene.camera.top;scene.resize();}scene.controls.update();}
function projection(value){if(!scene)return;const old=scene.camera;if((value==='parallel')===!!old.isOrthographicCamera)return;const r=scene.canvas.parentElement.getBoundingClientRect(),aspect=r.width/Math.max(1,r.height);let camera;if(value==='parallel'){const h=old.position.distanceTo(scene.controls.target)*Math.tan(THREE.MathUtils.degToRad(18));camera=new THREE.OrthographicCamera(-h*aspect,h*aspect,h,-h,.05,10000);}else camera=new THREE.PerspectiveCamera(36,aspect,.05,10000);camera.position.copy(old.position);camera.quaternion.copy(old.quaternion);camera.up.copy(old.up);scene.camera=camera;scene.controls.object=camera;gizmo.camera=camera;scene.controls.update();}
function standardView(name){if(!scene)return;const target=scene.controls.target.clone(),distance=Math.max(5,scene.camera.position.distanceTo(target));scene.camera.up.set(0,1,0);const offset=name==='top'?new THREE.Vector3(0,distance,0):name==='front'?new THREE.Vector3(0,0,distance):name==='right'?new THREE.Vector3(distance,0,0):new THREE.Vector3(1,1.1,1.3).normalize().multiplyScalar(distance);if(name==='top')scene.camera.up.set(0,0,-1);scene.camera.position.copy(target).add(offset);scene.controls.maxPolarAngle=name==='top'?Math.PI:Math.PI-.01;scene.controls.update();}
function refresh(){const cad=doc();if(lastFloor!==bridge.getFloorId()){ids=[];lastFloor=bridge.getFloorId();}ids=ids.filter(id=>entities().some(e=>e.id===id));if(scene){projection(cad.view.projection);if(!root||!root.parent)updateModels();else attachGizmo();applyView();}drawPlan();if(active){renderPanel();renderInspector();}}
function tabs(){return `<div class="chips">${[['create','Create'],['organize','Organize'],['views','Views'],['files','Files']].map(([id,name])=>`<button class="chip ${section===id?'active':''}" data-cad-section="${id}">${name}</button>`).join('')}</div>`;}
function renderPanel(){$('#panel-eyebrow').textContent='BUILD BEYOND THE FLOOR PLAN';$('#panel-title').textContent='Modeling studio';$('#library-count').hidden=false;$('#library-count').textContent=entities().length;const el=$('#panel-content');let html=tabs();
if(section==='create')html+=`<p class="panel-copy">Draw a profile in 2D, then extrude it into an editable solid. All dimensions below use meters.</p><div class="cad-tool-grid">${[['rectangle','▭','Rectangle'],['circle','◯','Circle'],['polygon','⬡','Polygon'],['line','╱','Line / path']].map(([type,ic,name])=>`<button class="build-button ${drawing===type?'active':''}" data-draw="${type}"><span class="cad-tool-icon">${ic}</span><strong>${name}</strong></button>`).join('')}</div><div class="dialog-actions"><button id="cad-finish" class="button subtle" ${!drawing?'disabled':''}>Finish · Enter</button><button id="cad-cancel" class="button subtle" ${!drawing?'disabled':''}>Cancel</button></div><div class="separator"></div><div class="property-heading">Solid primitives</div><div class="cad-tool-grid">${[['box','▣','Box'],['cylinder','▤','Cylinder'],['sphere','◉','Sphere'],['pipe','⌁','Pipe path']].map(([type,ic,name])=>`<button class="build-button" data-primitive="${type}"><span class="cad-tool-icon">${ic}</span><strong>${name}</strong></button>`).join('')}</div><div class="separator"></div><label class="field">Grid / move snap (meters)<select id="cad-snap">${[0,.01,.05,.1,.5,1].map(n=>`<option ${snap===n?'selected':''} value="${n}">${n||'Off'}</option>`).join('')}</select></label><p class="small-label">Endpoint, midpoint, grid, and axis alignment are available while drawing. Polygon/path: Enter finishes. Esc cancels.</p><div class="tip-card"><h4>From furniture to geometry</h4><p>Switch to Furnish, select a piece, then return here to convert it to editable triangles.</p><button id="cad-convert-home">Convert selected furniture</button></div>`;
if(section==='organize')html+=`<div class="property-heading">Outliner <span>${entities().length} MODELS</span></div><div class="cad-outliner">${entities().map(e=>`<div class="cad-outline-row ${ids.includes(e.id)?'selected':''}"><input type="checkbox" aria-label="Select ${esc(e.name)}" data-pick="${e.id}" ${ids.includes(e.id)?'checked':''}/><button data-model-select="${e.id}" title="${esc(e.name)}">${esc(e.name)}${e.definitionId?' ◇':''}</button><button data-model-visible="${e.id}" title="Toggle visibility" aria-label="Toggle visibility of ${esc(e.name)}">${e.visible?'◉':'○'}</button><button data-model-lock="${e.id}" title="Toggle lock" aria-label="Toggle lock of ${esc(e.name)}">${e.locked?'▣':'▫'}</button></div>`).join('')||'<p class="panel-copy">Create a model to begin.</p>'}</div><div class="dialog-actions"><button id="cad-group" class="button subtle">Group selection</button><button id="cad-ungroup" class="button subtle">Ungroup</button></div><div class="separator"></div><div class="property-heading">Tags <button id="cad-add-tag" class="icon-btn" title="Add tag">+</button></div>${doc().tags.map(t=>`<div class="cad-tag-row"><span style="background:${t.color}"></span><label>${esc(t.name)}</label><button data-tag-visible="${t.id}">${t.visible?'Visible':'Hidden'}</button></div>`).join('')}<div class="separator"></div><button id="cad-components" class="button subtle full-width">PC component library</button>`;
if(section==='views')html+=`<div class="property-heading">Camera</div><div class="cad-tool-grid">${['iso','top','front','right'].map(v=>`<button class="button subtle" data-camera="${v}">${v==='iso'?'Isometric':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><label class="field cad-gap">Projection<select id="cad-projection"><option value="perspective" ${doc().view.projection==='perspective'?'selected':''}>Perspective</option><option value="parallel" ${doc().view.projection==='parallel'?'selected':''}>Parallel</option></select></label><label class="field cad-gap">Display style<select id="cad-style">${['textured','monochrome','wireframe','xray'].map(s=>`<option value="${s}" ${doc().view.style===s?'selected':''}>${s==='xray'?'X-ray':s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></label><div class="separator"></div><div class="property-heading">Section plane</div><label class="cad-checkbox"><input id="cad-section-enabled" type="checkbox" ${doc().view.section.enabled?'checked':''}/>Enable clipping</label><div class="field-grid cad-gap"><label class="field">Axis<select id="cad-section-axis">${['x','y','z'].map(a=>`<option ${doc().view.section.axis===a?'selected':''}>${a}</option>`).join('')}</select></label><label class="field">Keep below (m)<input type="number" id="cad-section-offset" min="-1000" max="1000" step=".1" value="${doc().view.section.offset}"/></label></div><p class="small-label">A visual section, without cap faces. Model exports retain the complete underlying geometry.</p><div class="separator"></div><button id="cad-save-scene" class="button primary full-width">Save this view as a scene</button>${doc().scenes.map(s=>`<div class="cad-scene-row"><button data-scene="${s.id}">${esc(s.name)}</button><button data-delete-scene="${s.id}" aria-label="Remove scene ${esc(s.name)}">×</button></div>`).join('')}`;
if(section==='files')html+=`<p class="panel-copy">Import static triangle models and exchange designs with other tools. Imported coordinates are treated as meters; use the Scale fields to adjust.</p><button id="cad-import-model" class="button primary full-width">Import GLB / OBJ / STL</button><button id="cad-export-obj" class="button subtle full-width">Export current floor · OBJ</button><button id="cad-export-stl" class="button subtle full-width">Export current floor · STL</button><button id="cad-export-dxf" class="button subtle full-width">Export plan linework · DXF</button><div class="separator"></div><div class="property-heading">Drawing sheet</div><label class="field">A3 drawing scale<select id="cad-sheet-scale">${[20,25,50,100,200,500].map(n=>`<option value="${n}" ${n===100?'selected':''}>1:${n}</option>`).join('')}</select></label><button id="cad-sheet" class="button subtle full-width">Download A3 sheet · SVG</button><p class="small-label">A scaled plan sheet, not a LayOut document. Print the SVG at 100% to preserve scale. DXF export covers walls and planar model outlines; meshes and annotations are not exported to DXF.</p><div class="separator"></div><button id="cad-open-workspace" class="button subtle full-width">PC projects & recovery history</button><p class="panel-copy">SKP, native DWG, Trimble services, Ruby extensions, and live collaborative editing are not connected.</p>`;
el.innerHTML=html;for(const b of $$('[data-cad-section]'))b.onclick=()=>{section=b.dataset.cadSection;renderPanel();};for(const b of $$('[data-draw]'))b.onclick=()=>startDrawing(b.dataset.draw);for(const b of $$('[data-primitive]'))b.onclick=()=>safe(()=>{const type=b.dataset.primitive;if(type==='pipe'){startDrawing('pipe');return;}add(type,type==='box'?{width:1,depth:1,height:1}:type==='sphere'?{radius:.6,segments:32}:{radius:.5,height:1.5,segments:32});});$('#cad-finish')?.addEventListener('click',()=>safe(finishDrawing));$('#cad-cancel')?.addEventListener('click',cancelDrawing);$('#cad-snap')?.addEventListener('change',e=>{snap=Number(e.target.value);attachGizmo();});$('#cad-convert-home')?.addEventListener('click',()=>safe(convertFurniture));for(const b of $$('[data-model-select]'))b.onclick=()=>choose(b.dataset.modelSelect);for(const b of $$('[data-pick]'))b.onchange=()=>{ids=b.checked?[...ids,b.dataset.pick]:ids.filter(id=>id!==b.dataset.pick);refresh();};for(const b of $$('[data-model-visible]'))b.onclick=()=>change(cad=>{const e=cad.entities.find(e=>e.id===b.dataset.modelVisible);e.visible=!e.visible;});for(const b of $$('[data-model-lock]'))b.onclick=()=>change(cad=>{const e=cad.entities.find(e=>e.id===b.dataset.modelLock);e.locked=!e.locked;});$('#cad-group')?.addEventListener('click',()=>safe(()=>change(cad=>groupEntities(cad,ids))));$('#cad-ungroup')?.addEventListener('click',()=>safe(()=>change(cad=>{for(const e of selected())if(!e.locked)delete e.groupId;cad.groups=cad.groups.filter(g=>cad.entities.some(e=>e.groupId===g.id));})));$('#cad-add-tag')?.addEventListener('click',()=>textDialog('New tag','New tag',name=>change(cad=>cad.tags.push({id:cadId(),name,color:'#b9a0ff',visible:true}))));for(const b of $$('[data-tag-visible]'))b.onclick=()=>change(cad=>{const t=cad.tags.find(t=>t.id===b.dataset.tagVisible);t.visible=!t.visible;});$('#cad-components')?.addEventListener('click',()=>showComponents().catch(e=>bridge.toast(e.message)));
for(const b of $$('[data-camera]'))b.onclick=()=>standardView(b.dataset.camera);$('#cad-projection')?.addEventListener('change',e=>change(cad=>cad.view.projection=e.target.value));$('#cad-style')?.addEventListener('change',e=>change(cad=>cad.view.style=e.target.value));for(const selector of ['#cad-section-enabled','#cad-section-axis','#cad-section-offset'])$(selector)?.addEventListener('change',()=>safe(()=>change(cad=>{const offset=Number($('#cad-section-offset').value);if(!Number.isFinite(offset)||Math.abs(offset)>1000)throw Error('Section offset must be within ±1000 m.');cad.view.section={enabled:$('#cad-section-enabled').checked,axis:$('#cad-section-axis').value,offset};})));$('#cad-save-scene')?.addEventListener('click',()=>{if(!scene)return;textDialog('Name this scene','View '+(doc().scenes.length+1),name=>change(cad=>cad.scenes.push({id:cadId(),name,floorId:bridge.getFloorId(),position:scene.camera.position.toArray(),target:scene.controls.target.toArray(),up:scene.camera.up.toArray(),view:structuredClone(cad.view)})));});for(const b of $$('[data-scene]'))b.onclick=()=>{const s=structuredClone(doc().scenes.find(s=>s.id===b.dataset.scene));change(cad=>cad.view=s.view);bridge.setFloor(s.floorId);ids=[];if(scene){projection(s.view.projection);scene.camera.position.fromArray(s.position);scene.controls.target.fromArray(s.target);scene.camera.up.fromArray(s.up||[0,1,0]);scene.controls.update();}refresh();};for(const b of $$('[data-delete-scene]'))b.onclick=()=>change(cad=>cad.scenes=cad.scenes.filter(s=>s.id!==b.dataset.deleteScene));$('#cad-import-model')?.addEventListener('click',()=>input.click());$('#cad-export-obj')?.addEventListener('click',()=>exportModel('obj'));$('#cad-export-stl')?.addEventListener('click',()=>exportModel('stl'));$('#cad-export-dxf')?.addEventListener('click',()=>bridge.download(exportDXF(bridge.getFloor(),doc()),bridge.slug()+'.dxf','application/dxf'));$('#cad-sheet')?.addEventListener('click',()=>safe(exportSheet));$('#cad-open-workspace')?.addEventListener('click',()=>bridge.getWorkspace()?.openDialog());}
function field(key,label,value,disabled=false){return `<label class="field">${label}<input data-cad-field="${key}" type="number" step=".01" value="${rounded(value)}" ${disabled?'disabled':''}/></label>`;}
function renderInspector(){const el=$('#inspector-content'),list=selected();$('#inspector').classList.toggle('has-selection',!!list.length);if(!list.length){el.innerHTML='<span class="eyebrow">MODELING WORKSPACE</span><h2>Shape the possibilities.</h2><div class="overview-hero"><h3>Draw. Extrude.<br>Make it your own.</h3><p>Create profiles in the plan view or begin with a solid primitive. Select a model here or in the outliner to edit it.</p></div><p class="panel-copy">Gizmo: T move · E rotate · S scale<br>Drawing: L line · R rectangle · C circle<br>Finish a path: Enter · Cancel: Esc</p><div class="tip-card"><h4>One project, one history</h4><p>Models, components, tags, and scenes save with your house. Undo/redo covers both home design and modeling changes.</p></div>';return;}const one=list.length===1?list[0]:null,editable=canEdit(),shape=one&&resolveShape(doc(),one),p=shape?.params;let html=`<span class="eyebrow">${one?.definitionId?'LINKED COMPONENT':'MODEL PROPERTIES'}</span><h2>${one?esc(one.name):list.length+' models selected'}</h2><div class="chips">${[['translate','Move'],['rotate','Rotate'],['scale','Scale']].map(([value,label])=>`<button class="chip ${mode===value?'active':''}" data-gizmo="${value}">${label}</button>`).join('')}</div><label class="field">Gizmo coordinates<select id="cad-space"><option value="world" ${space==='world'?'selected':''}>World axes</option><option value="local" ${space==='local'?'selected':''}>Local axes</option></select></label><button id="cad-fit-selection" class="button subtle full-width">Fit selection</button>`;
if(one){html+=`<div class="separator"></div><label class="field">Name<input id="cad-name" maxlength="100" value="${esc(one.name)}" ${!editable?'disabled':''}/></label><label class="field cad-gap">Tag<select id="cad-entity-tag" ${!editable?'disabled':''}>${doc().tags.map(t=>`<option value="${t.id}" ${one.tagId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="separator"></div><div class="property-heading">Position <span>METERS</span></div><div class="cad-three-fields">${one.position.map((v,i)=>field('position.'+i,['X','Y','Z'][i],v,!editable)).join('')}</div><div class="property-heading cad-gap">Rotation <span>DEGREES</span></div><div class="cad-three-fields">${one.rotation.map((v,i)=>field('rotation.'+i,['X','Y','Z'][i],v,!editable)).join('')}</div><div class="property-heading cad-gap">Scale <span>NEGATIVE = MIRROR</span></div><div class="cad-three-fields">${one.scale.map((v,i)=>field('scale.'+i,['X','Y','Z'][i],v,!editable)).join('')}</div><div class="separator"></div><div class="property-heading">${one.definitionId?'Shared component geometry':'Geometry'}</div><div class="field-grid">${['width','depth','height','radius','segments'].filter(k=>p[k]!==undefined).map(k=>field('params.'+k,k[0].toUpperCase()+k.slice(1),p[k],!editable)).join('')}</div>${['rectangle','circle','polygon','extrusion','box','cylinder'].includes(shape.type)?`<label class="field cad-gap">Extrusion height (m)<input id="cad-extrude-height" type="number" step=".1" value="${p.height||1}" ${!editable?'disabled':''}/></label><button id="cad-extrude" class="button primary full-width" ${!editable?'disabled':''}>Apply profile extrusion</button><label class="field cad-gap">Profile offset (m)<input id="cad-offset-distance" type="number" step=".05" value=".1" ${!editable?'disabled':''}/></label><button id="cad-offset" class="button subtle full-width" ${!editable?'disabled':''}>Offset profile</button>`:''}${['polygon','extrusion'].includes(shape.type)?`<label class="field cad-gap">Profile X,Z vertices<textarea id="cad-profile-points" rows="4" ${!editable?'disabled':''}>${esc(JSON.stringify(p.points))}</textarea></label><button id="cad-profile-update" class="button subtle full-width" ${!editable?'disabled':''}>Update vertices</button>`:''}<label class="field color-field cad-gap">Material color<input id="cad-color" type="color" value="${one.color}" ${!editable?'disabled':''}/></label><div class="separator"></div><div class="dialog-actions"><button id="cad-component" class="button subtle" ${!editable?'disabled':''}>${one.definitionId?'Save to PC library':'Make component'}</button>${one.definitionId?'<button id="cad-unique" class="button subtle">Make unique</button>':''}</div>${one.definitionId?'<p class="small-label">Geometry edits affect linked instances. Transforms and colors are per instance.</p>':''}`;}
else html+='<p class="panel-copy">Use the gizmo to transform the selected models together. Shift-click models or use the outliner checkboxes for multi-selection.</p>';
html+=`<div class="separator"></div><div class="property-heading">Solid operations <span>SELECT TWO</span></div><div class="cad-tool-grid">${['union','subtract','intersect'].map(op=>`<button class="button subtle" data-boolean="${op}" ${!editable||list.length!==2?'disabled':''}>${op[0].toUpperCase()+op.slice(1)}</button>`).join('')}</div><p class="small-label">Subtract removes the second selected solid from the first. Experimental mesh operations require closed, non-self-intersecting solids.</p><div class="object-actions"><button id="cad-duplicate" ${!editable?'disabled':''}>⧉<span>Duplicate</span></button><button id="cad-mirror" ${!editable?'disabled':''}>↔<span>Mirror X</span></button><button id="cad-delete" ${!editable?'disabled':''}>×<span>Delete</span></button></div>${!editable?'<p class="workspace-warning">Locked selection. Unlock it in Organize to edit.</p>':''}`;el.innerHTML=html;
for(const b of $$('[data-gizmo]'))b.onclick=()=>{mode=b.dataset.gizmo;attachGizmo();renderInspector();};$('#cad-space').onchange=e=>{space=e.target.value;attachGizmo();};$('#cad-fit-selection').onclick=fitSelection;if(one){$('#cad-name').onchange=e=>safe(()=>change(()=>one.name=e.target.value.trim().slice(0,100)||one.name));$('#cad-entity-tag').onchange=e=>change(()=>one.tagId=e.target.value);for(const input of $$('[data-cad-field]')){const handler=()=>safe(()=>{const [key,k]=input.dataset.cadField.split('.'),value=Number(input.value);if(!Number.isFinite(value))throw Error('Enter a finite number.');const object=key==='params'?p:one[key];if(object[k]===value)return;change(()=>object[k]=value);});input.onchange=handler;input.onblur=handler;}$('#cad-color').onchange=e=>change(()=>one.color=e.target.value);$('#cad-extrude')?.addEventListener('click',()=>safe(()=>{const height=Number($('#cad-extrude-height').value);if(!Number.isFinite(height)||Math.abs(height)<.001||Math.abs(height)>200)throw Error('Use an extrusion height between ±200 m, at least 1 mm.');const points=structuredClone(profileFor(shape));change(()=>{shape.type='extrusion';shape.params={points,height};});}));$('#cad-offset')?.addEventListener('click',()=>safe(()=>{const points=offsetProfile(profileFor(shape),Number($('#cad-offset-distance').value));change(()=>{shape.type=shape.type==='extrusion'||shape.type==='box'||shape.type==='cylinder'?'extrusion':'polygon';shape.params=shape.type==='extrusion'?{points,height:p.height||1}:{points};});}));$('#cad-profile-update')?.addEventListener('click',()=>safe(()=>{const points=JSON.parse($('#cad-profile-points').value);validateProfile(points);change(()=>p.points=points);}));$('#cad-component')?.addEventListener('click',()=>{if(one.definitionId){const def=doc().definitions.find(d=>d.id===one.definitionId);bridge.getWorkspace().saveComponent(def).then(()=>bridge.toast('Component saved in the PC library.')).catch(e=>bridge.toast(e.message));}else textDialog('Component name',one.name,name=>change(cad=>makeComponent(cad,one,name)));});$('#cad-unique')?.addEventListener('click',()=>change(cad=>makeUnique(cad,one)));}
for(const b of $$('[data-boolean]'))b.onclick=()=>safe(()=>{const [a,bEntity]=ids.map(id=>entities().find(e=>e.id===id));const result=booleanEntity(doc(),a,bEntity,b.dataset.boolean);change(cad=>{cad.entities=cad.entities.filter(e=>!ids.includes(e.id));cad.entities.push(result);});ids=[result.id];refresh();});$('#cad-duplicate').onclick=()=>safe(duplicateSelected);$('#cad-delete').onclick=()=>safe(deleteSelected);$('#cad-mirror').onclick=()=>safe(()=>{if(!canEdit())return;change(()=>selected().forEach(e=>e.scale[0]*=-1));});}
function duplicateSelected(){if(!canEdit())return;const copies=selected().map(duplicateEntity);change(cad=>cad.entities.push(...copies));ids=copies.map(e=>e.id);refresh();}
function deleteSelected(){if(!canEdit())return;change(cad=>{cad.entities=cad.entities.filter(e=>!ids.includes(e.id));cad.groups=cad.groups.filter(g=>cad.entities.some(e=>e.groupId===g.id));});ids=[];refresh();}
function startDrawing(type){drawing=type;points=[];bridge.setView('2d');$('#plan-svg').style.cursor='crosshair';bridge.toast(type==='rectangle'?'Click two opposite corners.':type==='circle'?'Click a center, then a radius point.':'Click path vertices; press Enter to finish.');renderPanel();bridge.renderPlan();}
function cancelDrawing(){drawing=null;points=[];$('#plan-svg').style.cursor='default';renderPanel();bridge.renderPlan();}
function point(e){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('#plan-svg').getScreenCTM().inverse()),anchors=[...points];for(const w of bridge.getFloor().walls)anchors.push([w.x1,w.z1],[w.x2,w.z2],[(w.x1+w.x2)/2,(w.z1+w.z2)/2]);for(const e of entities().filter(visible)){let path;try{path=profileFor(resolveShape(doc(),e));}catch{continue;}const matrix=new THREE.Matrix4().compose(new THREE.Vector3(...e.position),new THREE.Quaternion().setFromEuler(new THREE.Euler(...e.rotation.map(THREE.MathUtils.degToRad),'XYZ')),new THREE.Vector3(...e.scale));const world=path.map(([x,z])=>new THREE.Vector3(x,0,z).applyMatrix4(matrix));for(let i=0;i<world.length;i++){const a=world[i],b=world[(i+1)%world.length];anchors.push([a.x,a.z],[(a.x+b.x)/2,(a.z+b.z)/2]);}}const result=snapPoint([p.x,p.y],anchors,snap||.0001,.12,points.at(-1));return result.point;}
$('#plan-svg').addEventListener('pointerdown',e=>{if(!active)return;const target=e.target.closest('[data-cad-id]');if(!drawing){if(target){e.stopImmediatePropagation();e.preventDefault();choose(target.dataset.cadId,e.shiftKey||e.ctrlKey);return;}return;}e.stopImmediatePropagation();e.preventDefault();if(e.button!==0)return;const p=point(e);if(points.length&&Math.hypot(p[0]-points.at(-1)[0],p[1]-points.at(-1)[1])<.001)return;points.push(p);if(['rectangle','circle'].includes(drawing)&&points.length===2)safe(finishDrawing);else bridge.renderPlan();},{capture:true});
function finishDrawing(){if(!drawing)return;if(points.length<(drawing==='polygon'?3:2))throw Error('Add more points before finishing.');let type=drawing,params,position=[0,.04,0];if(type==='rectangle'){const [a,b]=points;params={width:Math.abs(b[0]-a[0]),depth:Math.abs(b[1]-a[1])};if(params.width<.001||params.depth<.001)throw Error('Rectangle dimensions must be at least 1 mm.');position=[(a[0]+b[0])/2,.04,(a[1]+b[1])/2];}else if(type==='circle'){const [a,b]=points;params={radius:Math.hypot(b[0]-a[0],b[1]-a[1]),segments:32};position=[a[0],.04,a[1]];}else{const center=points.reduce((a,p)=>[a[0]+p[0]/points.length,a[1]+p[1]/points.length],[0,0]);position=[center[0],.04,center[1]];if(type==='polygon'){params={points:points.map(p=>[p[0]-center[0],p[1]-center[1]])};validateProfile(params.points);}else params={points:points.map(p=>[p[0]-center[0],0,p[1]-center[1]]),...(type==='pipe'?{radius:.08,segments:16}:{})};}const e=newEntity(type,bridge.getFloorId(),params,position);change(cad=>cad.entities.push(e));ids=[e.id];cancelDrawing();refresh();}
function drawPlan(){const svg=$('#plan-svg');svg.querySelector('#cad-plan-overlay')?.remove();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='cad-plan-overlay';let html='';for(const e of entities().filter(visible)){const shape=resolveShape(doc(),e);let vertices,closed=true;try{vertices=profileFor(shape);}catch{if(['line','pipe'].includes(shape.type)){vertices=shape.params.points.map(p=>[p[0],p[2]]);closed=false;}else if(root){let mesh;root.traverse(o=>{if(o.userData.id===e.id)mesh=o;});if(mesh){const b=new THREE.Box3().setFromObject(mesh);vertices=[[b.min.x,b.min.z],[b.max.x,b.min.z],[b.max.x,b.max.z],[b.min.x,b.max.z]];html+=`<polygon data-cad-id="${e.id}" points="${vertices.map(p=>p.join(',')).join(' ')}" fill="${e.color}" fill-opacity=".6" stroke="${ids.includes(e.id)?'#8e5bb7':'#50445e'}" stroke-width=".035"/>`;}continue;}else continue;}const rotation=THREE.MathUtils.degToRad(e.rotation[1]);vertices=vertices.map(([x,z])=>[e.position[0]+x*e.scale[0]*Math.cos(rotation)+z*e.scale[2]*Math.sin(rotation),e.position[2]-x*e.scale[0]*Math.sin(rotation)+z*e.scale[2]*Math.cos(rotation)]);html+=`<${closed?'polygon':'polyline'} data-cad-id="${e.id}" points="${vertices.map(p=>p.join(',')).join(' ')}" fill="${closed?e.color:'none'}" fill-opacity=".65" stroke="${ids.includes(e.id)?'#9b62c8':'#51465c'}" stroke-width=".035"/>`;}
if(active&&points.length)html+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#a174c7" stroke-width=".04"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r=".055" fill="#fff" stroke="#a174c7" stroke-width=".025"/>`).join('')}`;g.innerHTML=html;svg.append(g);}
function textDialog(title,value,callback){bridge.modal(`<span class="eyebrow">MODELING STUDIO</span><h2>${esc(title)}</h2><form id="cad-name-form"><label class="field">Name<input id="cad-dialog-name" required maxlength="100" value="${esc(value)}"/></label><div class="dialog-actions"><button class="button primary" type="submit">Save</button></div></form>`);$('#cad-name-form').onsubmit=e=>{e.preventDefault();const value=$('#cad-dialog-name').value.trim();if(!value)return;$('#modal').close();safe(()=>callback(value));};}
async function showComponents(){const workspace=bridge.getWorkspace(),components=await workspace.components();bridge.modal(`<span class="eyebrow">REUSABLE MODELS ON THIS PC</span><h2>Component library</h2><p>Insert a saved component into this project. Its linked instances will share editable geometry within the project.</p><div class="export-options">${components.map(c=>`<button class="export-option" data-insert-component="${c.id}"><span><strong>${esc(c.name)}</strong><small>Revision ${c.revision}</small></span></button>`).join('')||'<p>No components yet. Make a component from a selected model and save it to this library.</p>'}</div>`);for(const b of $$('[data-insert-component]'))b.onclick=async()=>{try{const original=await workspace.component(b.dataset.insertComponent);const definition={...structuredClone(original),id:cadId()};const e=newEntity(definition.shape.type,bridge.getFloorId(),{});e.definitionId=definition.id;delete e.shape;e.name=definition.name;change(cad=>{cad.definitions.push(definition);cad.entities.push(e);});ids=[e.id];$('#modal').close();refresh();}catch(error){bridge.toast(error.message);}};}
async function exportModel(format){if(!scene){bridge.toast('3D export requires WebGL.');return;}try{let data,type;if(format==='obj'){const {OBJExporter}=await import('./vendor/OBJExporter.js');data=new OBJExporter().parse(scene.content);type='text/plain';}else{const {STLExporter}=await import('./vendor/STLExporter.js');data=new STLExporter().parse(scene.content,{binary:true});type='model/stl';}bridge.download(data,bridge.slug()+'.'+format,type);bridge.toast(format.toUpperCase()+' exported.');}catch(error){bridge.toast(error.message);}}
function planBounds(){const b=floorBounds(bridge.getFloor());if(root){const box=new THREE.Box3().setFromObject(root);if(!box.isEmpty()){const x=Math.min(b.x,box.min.x),z=Math.min(b.z,box.min.z);b.w=Math.max(b.x+b.w,box.max.x)-x;b.d=Math.max(b.z+b.d,box.max.z)-z;b.x=x;b.z=z;}}return b;}
function exportSheet(){const scale=Number($('#cad-sheet-scale').value),b=planBounds(),width=b.w*1000/scale,height=b.d*1000/scale;if(width>370||height>215)throw Error('This floor does not fit on A3 at that scale. Choose a larger scale denominator.');const plan=$('#plan-svg').innerHTML;const data=`<svg xmlns="http://www.w3.org/2000/svg" width="420mm" height="297mm" viewBox="0 0 420 297"><rect width="420" height="297" fill="white"/><rect x="10" y="10" width="400" height="277" fill="none" stroke="#555" stroke-width=".3"/><text x="20" y="24" font-family="sans-serif" font-size="6">${esc(bridge.getProject().name)}</text><text x="20" y="34" font-family="sans-serif" font-size="3.5">${esc(bridge.getFloor().name)} · Plan · 1:${scale} · Geometry in meters</text><svg x="${(420-width)/2}" y="${45+(215-height)/2}" width="${width}" height="${height}" viewBox="${b.x} ${b.z} ${b.w} ${b.d}" stroke="none">${plan}</svg><path d="M10 267h400" stroke="#555" stroke-width=".3"/><text x="20" y="277" font-family="sans-serif" font-size="3">HESTIA 2.0 · DESIGN VISUALIZATION · Print at 100% / actual size</text><text x="20" y="283" font-family="sans-serif" font-size="2.5">Not certified construction documentation. Verify all dimensions independently.</text></svg>`;bridge.download(data,bridge.slug()+'-A3-1-'+scale+'.svg','image/svg+xml');}
function convertFurniture(){const selection=rememberedHome;if(selection?.kind!=='item'||!scene)throw Error('First select a furniture piece in Furnish, then return to Model.');const source=scene.content.children.find(o=>o.userData.id===selection.id);if(!source)throw Error('Furniture is unavailable in this view.');source.updateMatrixWorld(true);const vertices=[];source.traverse(o=>{if(!o.isMesh)return;const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);for(const v of geometryData(g).params.vertices)vertices.push(v);g.dispose();});if(vertices.length>300000)throw Error('This furniture model has too many triangles.');const item=bridge.getFloor().items.find(i=>i.id===selection.id),e=newEntity('mesh',bridge.getFloorId(),{vertices});e.name=item.name+' mesh';e.color=item.color;bridge.mutate(project=>{ensureCAD(project).entities.push(e);bridge.getFloor().items=bridge.getFloor().items.filter(i=>i.id!==selection.id);});ids=[e.id];refresh();}
document.addEventListener('keydown',e=>{if(!active||$('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const k=e.key.toLowerCase();if(e.ctrlKey||e.metaKey){if(k==='d'){e.preventDefault();e.stopImmediatePropagation();safe(duplicateSelected);}if(k==='g'){e.preventDefault();e.stopImmediatePropagation();safe(()=>change(cad=>{if(e.shiftKey){selected().forEach(e=>delete e.groupId);cad.groups=cad.groups.filter(g=>cad.entities.some(e=>e.groupId===g.id));}else groupEntities(cad,ids);}));}return;}const keys={l:'line',r:'rectangle',c:'circle'};if(keys[k]){e.preventDefault();e.stopImmediatePropagation();startDrawing(keys[k]);}else if(['t','e','s'].includes(k)){e.preventDefault();e.stopImmediatePropagation();mode={t:'translate',e:'rotate',s:'scale'}[k];attachGizmo();renderInspector();}else if(k==='enter'&&drawing){e.preventDefault();e.stopImmediatePropagation();safe(finishDrawing);}else if(k==='escape'){e.stopImmediatePropagation();cancelDrawing();ids=[];refresh();}else if(['delete','backspace'].includes(k)){e.preventDefault();e.stopImmediatePropagation();safe(deleteSelected);}},{capture:true});
updateModels();
return{get active(){return active;},refresh,renderPanel,renderInspector,drawPlan,planBounds};
}
